disableCheck(room) {
  return room.exist == 1
},
// 列表视图：根据房屋原始 checked 状态同步表格勾选（支持跨楼幢勾选记忆）
syncListSelection() {
  const table = this.$refs.listTable
  if (!table || !this.flattenHouseList?.length) return
  this.isSyncingSelection = true
  table.clearSelection?.()
  this.flattenHouseList.forEach((row) => {
    if (row.checked == '1' || row.checked === 1) table.toggleRowSelection?.(row, true)
  })
  this.$nextTick(() => {
    this.isSyncingSelection = false
  })
},

